use App\Enums\OrderStatus;

public function ship(Order $order)
{
    if ($order->status !== OrderStatus::Paid) {
        abort(409);
    }

    $order->status = OrderStatus::Shipped;
    $order->save();

    return back();
}

public function wrap(Order $order)
{
    $order->options['gift_wrap'] = true;
    $order->save();

    return back();
}
